import perceivo


@perceivo.policy
async def parallel_executor_policy_internal(input: perceivo.primitives.PolicyInput) -> perceivo.primitives.PolicyOutput:
    rd = input.request_data or {}
    results = rd.get("results", {})
    errors = rd.get("errors", {})
    failure_strategy = rd.get("failure_strategy", "wait_all")

    # Merge all branch results into a single dict keyed by port name
    merged = {}
    for port_name, response in results.items():
        if isinstance(response, dict):
            merged[port_name] = response

    # Add metadata
    merged["_parallel_metadata"] = {
        "branches": list(results.keys()),
        "branch_count": len(results),
        "error_count": len(errors),
        "errors": errors if errors else None,
        "failure_strategy": failure_strategy,
    }

    perceivo.log.info(f"Parallel Policy: merged {len(results)} branch results")

    return perceivo.primitives.PolicyOutput(
        next_state="done",
        response_data=merged,
    )

