import perceivo
import json as _json


@perceivo.fsm
async def parallel_executor(input: perceivo.primitives.FsmInput) -> perceivo.primitives.FsmOutput:
    timeout = int(perceivo.params.get("timeout_seconds", 300))
    failure_strategy = perceivo.params.get("failure_strategy", "wait_all")
    states_raw = perceivo.params.get("states", "[]")

    # Parse states configuration
    try:
        states = _json.loads(states_raw) if isinstance(states_raw, str) else states_raw
        if not isinstance(states, list):
            states = []
    except (_json.JSONDecodeError, TypeError):
        states = []

    # Extract state port names and build label map
    state_ports = (
        [s.get("port_name", f"state_{i+1}") for i, s in enumerate(states)]
        if states else ["state_1", "state_2"]
    )

    # Map port_name -> custom label (falls back to port_name if no label set)
    port_label_map = {}
    if states:
        for i, s in enumerate(states):
            pn = s.get("port_name", f"state_{i+1}")
            port_label_map[pn] = s.get("label") or pn

    # Gather input data
    data = input.request_data or {}
    if input.artifact and input.artifact.data and isinstance(input.artifact.data, dict):
        data = {**input.artifact.data, **data}

    perceivo.log.info(
        f"Parallel Executor: launching {len(state_ports)} parallel branches",
        state_ports=state_ports,
        timeout=timeout,
        failure_strategy=failure_strategy,
    )


    # Execute all state ports in parallel via invoke_parallel
    # This uses Ray actors for true parallelism
    try:
        results = await perceivo.flow.invoke_parallel(
            port_names=state_ports,
            request_data=data,
            artifact=input.artifact,
            timeout_seconds=timeout,
            failure_strategy=failure_strategy,
        )
    except Exception as e:
        if failure_strategy == "ignore_failures":
            perceivo.log.warning(f"Parallel Executor: parallel execution failed but ignoring: {e}")
            results = {}
        else:
            raise

    # Extract response data and errors, using custom labels as keys
    branch_results = {}
    branch_errors = {}
    for port_name, result in results.items():
        label = port_label_map.get(port_name, port_name)
        if isinstance(result, dict):
            if result.get("error"):
                branch_errors[label] = result["error"]
            branch_results[label] = result.get("response_data", {})
        else:
            branch_results[label] = {}

    perceivo.log.info(f"Parallel Executor: {len(branch_results)} branches completed, {len(branch_errors)} errors")

    # Send results to policy for merge/aggregation
    policy_result = await perceivo.flow.invoke(
        port_name="policy",
        request_data={
            "results": branch_results,
            "errors": branch_errors,
            "failure_strategy": failure_strategy,
        },
    )

    # Get merged output from policy
    merged = {}
    if policy_result and isinstance(policy_result, dict):
        merged = policy_result.get("response_data", {})

    return perceivo.primitives.FsmOutput(
        artifact=perceivo.primitives.Artifact(
            type=perceivo.primitives.ArtifactType.JSON,
            data=merged,
            mime_type="application/json",
        ),
        response_data=merged,
    )

